// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller, address newDistributor) public {
        vm.assume(caller != address(this));
        vm.assume(newDistributor != address(0));
        bool ok;
        vm.prank(caller);
        try c.setRewardDistributor(newDistributor) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
